def seed_database(db: Session) -> None:
    """
    Seed DB1 and scan sessions if empty.
    Safe to call multiple times — skips individual duplicates gracefully.
    """
    if db.query(models.Asset).count() == 0:
        print("Seeding DB1 master — 87 asset records...")
        seeded = 0
        skipped = 0
        for rec in DB1_RECORDS:
            exists = db.query(models.Asset).filter(
                (models.Asset.epc == rec["epc"]) |
                (models.Asset.record_id == rec["record_id"])
            ).first()
            if exists:
                print(f"  Skipping duplicate: {rec['record_id']} / EPC {rec['epc']}")
                skipped += 1
                continue
            try:
                db.add(models.Asset(**rec))
                db.flush()
                seeded += 1
            except Exception as e:
                db.rollback()
                print(f"  Error seeding {rec['record_id']}: {e}")
                skipped += 1
        db.commit()
        print(f"DB1 seeded: {seeded} records inserted, {skipped} skipped.")
    else:
        print("DB1 already populated — skipping seed.")

    if db.query(models.ScanSession).count() == 0:
        print("Seeding 15 scan sessions...")
        seeded = 0
        for s in SESSIONS_DATA:
            exists = db.query(models.ScanSession).filter(
                models.ScanSession.session_id == s["session_id"]
            ).first()
            if exists:
                continue
            try:
                db.add(models.ScanSession(**s))
                db.flush()
                seeded += 1
            except Exception as e:
                db.rollback()
                print(f"  Error seeding {s['session_id']}: {e}")
        db.commit()
        print(f"Sessions seeded: {seeded} inserted.")
    else:
        print("Sessions already populated — skipping seed.")
